public interface IExternalContentIdLookup
{
    Task<string> GetContentItemIdAsync(string externalId);
}

public sealed class ExternalIdHandleProvider : IContentHandleProvider
{
    private const string Prefix = "external:";
    private readonly IExternalContentIdLookup _lookup;

    public ExternalIdHandleProvider(IExternalContentIdLookup lookup)
    {
        _lookup = lookup;
    }

    public int Order => 200;

    public Task<string> GetContentItemIdAsync(string handle)
    {
        if (!handle.StartsWith(Prefix, StringComparison.OrdinalIgnoreCase))
        {
            return Task.FromResult<string>(null);
        }

        return _lookup.GetContentItemIdAsync(handle[Prefix.Length..]);
    }
}

Span<int> CreateSpanOfInt()
{
    // This is legal according to the 7.2 span rules because they do not account
    // for a constructor in the form Span(ref T value) existing. 
    int local = 42;
    return new Span<int>(ref local);
}

void Swap(ref scoped Span<int> p1, ref scoped Span<int> p2)
{
    // Error: can't assign current parameter 2 to current parameter 1
    p2 = p1;

    // Error: can't assign current parameter 1 to current parameter 2
    p1 = p2;

    // Okay: as current parameter 1 and 2 can be converted to current method
    scoped Span<int> local1 = p1; 
    scoped Span<int> local2 = p2; 

    // Okay: however the safe-to-escape here is current parameter N, not 
    // current method so this could cause a bit of confusion later on
    Span<int> local3 = p1; 
    Span<int> local4 = p2; 

    // Okay: the safe-to-escape of the value is inferred in this case as it is 
    // done for ref locals today.
    ref Span<int> refLocal1 = ref p1;
    ref Span<int> refLocal2 = ref p2;
}

