  "$schema": "https://gofastmcp.com/public/schemas/fastmcp.json/v1.json",
  // WHERE does the server live?
  "source": {
    "path": "src/server.py",
    "entrypoint": "app"
  },
  // WHAT dependencies does it need?
  "environment": {
    "type": "uv",
    "python": "3.12",
    "dependencies": ["fastmcp[dev]"],
    "editable": "."
  },
  // HOW should it run?
  "deployment": {
    "transport": "http",
    "host": "127.0.0.1",
    "port": 8000,
    "log_level": "DEBUG",
    "env": {
      "DEBUG": "true",
      "ENV": "development"
    }
  }
}

{
    "peerDependencies": {
        "react-dom": "1"
    },
    "peerDependenciesMeta": {
        "react-dom": {
            "optional": true
        },
        // express is not specified in the peerDependencies field,
        // so pnpm will assume that any version of express is fine
        "express": {
            "optional": true
        }
    }
}
